"use client";
import * as React from "react";
import { useReferenceRef } from "@/lib/cojeev/reference-ref";
import { cn } from "@/lib/utils";
import { bounded,caretFrame } from "@/lib/cojeev/reference-text-math";
import { useReferenceText,useReferenceClock,type ReferenceTextSize } from "@/lib/cojeev/reference-text-motion";
export type CaretSwapProps=Omit<React.ComponentProps<"div">,"children">&{fromText:string;toText:string;duration?:number;paused?:boolean;replayKey?:string|number;size?:ReferenceTextSize};
/** A caret expands right-to-left, collapses, then types whole graphemes into the reserved footprint. */
export function CaretSwap({fromText,toText,duration=4200,paused=false,replayKey=0,size="default",className,ref,...props}:CaretSwapProps){
 const {host:hostRef,running}=useReferenceText(paused),[progress,setProgress]=React.useState(1);
 const cycle=bounded(duration,1600,12000,4200);
 useReferenceClock(running,time=>{const p=bounded(time/cycle,0,1,1);setProgress(p);return p<1;},`${replayKey}:${fromText}:${toText}:${cycle}`);
 const state=caretFrame(fromText,toText,running?progress:1);
 return <div {...props} ref={useReferenceRef(hostRef,ref)} data-slot="caret-swap" data-size={size} data-running={running&&progress<1} data-state={state.phase} className={cn("v-caret-swap",className)}>
 <span className="v-caret-swap__accessible">{toText}</span>
 <span aria-hidden="true" className="v-caret-swap__frame"><span className="v-caret-swap__measure">{fromText}</span><span className="v-caret-swap__measure">{toText}</span>
 <span className="v-caret-swap__text">{state.text}{(state.phase==="typing"||state.phase==="complete")&&<span className="v-caret-swap__caret"/>}</span>
 {(state.phase==="covering"||state.phase==="collapsing")&&<span className="v-caret-swap__block" style={{width:`${state.cover*100}%`,left:state.phase==="collapsing"?0:undefined,right:state.phase==="covering"?0:undefined}}/>}
 </span></div>;
}

@layer cojeev-states {
.v-caret-swap { display:grid; position:relative; place-items:center; min-inline-size:0; inline-size:100%; min-block-size:260px; padding:24px; overflow:hidden; border-radius:var(--radius-panel,24px); color:var(--v-text); background:var(--v-beige); font-family:var(--font-display,"Bricolage Grotesque",sans-serif); font-size:clamp(2rem,5vw,3.5rem); line-height:1.15; isolation:isolate; }
.v-caret-swap[data-size="sm"] { min-block-size:200px; font-size:clamp(1.5rem,4vw,2.5rem); padding:16px; }
.v-caret-swap[data-size="lg"] { min-block-size:340px; font-size:clamp(2.25rem,6vw,4.5rem); }
.v-caret-swap__accessible { position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip-path:inset(50%); white-space:nowrap; border:0; }
.v-caret-swap__frame {position:relative;display:grid;max-inline-size:100%;overflow-wrap:anywhere;line-height:1.3;}
.v-caret-swap__measure,.v-caret-swap__text {grid-area:1/1;max-inline-size:100%;padding-inline-end:.16em;}
.v-caret-swap__measure {visibility:hidden;}
.v-caret-swap__caret {display:inline-block;inline-size:.07em;block-size:.85em;background:var(--v-accent-ink);margin-inline-start:.04em;vertical-align:-.04em;}
.v-caret-swap__block {position:absolute;inset-block:0;background:linear-gradient(150deg,var(--v-pink),var(--v-blue));border-radius:.08em;}

}
